import{_ as t,o as a,c as s,ak as n}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy local data contract","description":"Game design · Technical design · Offline records","frontmatter":{"title":"Chainy local data contract","description":"Game design · Technical design · Offline records","source":"docs/design/database-schema.md","category":"Game & system design","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/design/database-schema.md","filePath":"content/docs/design/database-schema.md"}'),r={name:"content/docs/design/database-schema.md"};function o(i,e,c,d,l,p){return a(),s("div",null,[...e[0]||(e[0]=[n('<div><h1 id="chainy-local-data-contract">Chainy local data contract<a class="header-anchor" href="#chainy-local-data-contract" aria-label="Link to this section">​</a></h1><p><a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">Game design</a> · <a href="/Chainy-Docs/content/docs/technical-design.html">Technical design</a> · <a href="/Chainy-Docs/content/docs/offline-data-plan.html">Offline records</a></p><p><strong>Documentation and preparation only until the owner&#39;s explicit FINAL approval.</strong> Christian owns technical schema decisions; Sean records the contract. The logical records below are proposed requirements, not implemented tables or a migration.</p><h2 id="current-progress-contract">Current progress contract<a class="header-anchor" href="#current-progress-contract" aria-label="Link to this section">​</a></h2><p>SQLite is the local store. The November 11 audit found <code>IDatabaseSystem</code>, a queued SQLite connection, and <code>DatabaseBridge.RunInTransactionAsync</code>. It did not verify the new journey schema or Android persistence. Use the existing database owner and the smallest compatible additive change after development is authorized.</p><table><thead><tr><th>Logical record</th><th>Required fields or meaning</th></tr></thead><tbody><tr><td>Profile/version</td><td>Stable local profile ID; schema and content versions; no authenticated identity or cross-device recovery</td></tr><tr><td>World progress</td><td>Profile/world key, tutorial complete, and next lesson position in the fixed 13-lesson sequence</td></tr><tr><td>Collection</td><td>The world&#39;s required stable lesson IDs recorded once; encyclopedia entries and count derive from the same completion set</td></tr><tr><td>Current encounter</td><td>Current minigame lesson and step: 0 = item needed; 1 = item saved, NPC needed; 2 = NPC saved, facility may launch</td></tr><tr><td>Quiz attempt</td><td>Unique attempt ID, profile, world, question-content version, all 13 ordered question IDs, and active/abandoned/completed status</td></tr><tr><td>Question response</td><td>Attempt/question key, first selected answer and correctness, and whether the question is now correctly resolved</td></tr><tr><td>Required review</td><td>Reference to a successfully completed attempt; retained independently of later replay outcomes</td></tr><tr><td>Return checkpoint</td><td>Originating world/lesson and safe island location identity; no transient animation or mid-round state</td></tr></tbody></table><p>Stable IDs, not display names or interaction counts, identify progress. Exactly one question corresponds to each of the world&#39;s 13 lessons. Teaching order is separate from alphabetical encyclopedia display. The audited encyclopedia adapter treated guest IDs as memory-only; durable guest behavior is therefore an integration question, not a current guarantee. If a guest profile remains playable, give it isolated persistent progress under the same rules as other local profiles.</p><h2 id="ordered-lessons-and-prerequisites">Ordered lessons and prerequisites<a class="header-anchor" href="#ordered-lessons-and-prerequisites" aria-label="Link to this section">​</a></h2><p>Only an unlocked world with completed tutorial may advance its current lesson. Future lesson interactions cannot consume their objects or change completion. Earlier completed lessons may be revisited without incrementing counts. A normal lesson requires its Record action; a minigame lesson requires its assigned successful result from the current encounter.</p><p>For a minigame, persist step 0 → 1 after the item and step 1 → 2 after the NPC. Only step 2 permits the facility to launch the scene. Repeating an already committed prerequisite is harmless; a future step or wrong profile/lesson is rejected. Exit, load failure, or restart preserves the saved prerequisite step. Ordinary lessons and finished collections have no active prerequisite, represented as step 0.</p><p>A lesson transaction records completion, encyclopedia entry, next objective, collection status, and prerequisite reset together. A successful minigame result belongs to that same transaction. All 13 unique required entries yield Collection complete / Quiz required; this alone does not unlock the next world.</p><h2 id="thirteen-question-attempts">Thirteen-question attempts<a class="header-anchor" href="#thirteen-question-attempts" aria-label="Link to this section">​</a></h2><p>An attempt starts only after all 13 entries are recorded. Present one question at a time in the authored order. Persist the first submitted choice once, then track correction separately. A wrong choice keeps that question active; only a correct choice enables Next. Repeat submissions and save retries must not replace the first response or create extra attempts.</p><p>Finish requires all 13 questions correctly resolved. Atomically mark the attempt and required review complete; world access derives from that committed review and collection state. If access is cached, update it in the same transaction. Web3 completion unlocks Blockchain, Blockchain completion unlocks AI, and AI completion finishes the journey.</p><p>Show first responses as X/13 separately from completion after corrections. For an abandoned attempt, preserve only its actual submitted responses and partial status; do not represent unanswered questions as a finished score. Leaving an unfinished quiz abandons that attempt; returning starts all 13 questions in a new attempt. On relaunch, mark any interrupted active attempt abandoned before starting another. Pause alone does not abandon a surviving session. Replay creates a new attempt while preserving earlier world completion and unlocks.</p><h2 id="commit-failure-and-profile-isolation">Commit, failure, and profile isolation<a class="header-anchor" href="#commit-failure-and-profile-isolation" aria-label="Link to this section">​</a></h2><p>Publish new progress only after a successful commit. Serialize progress writes and revalidate the latest persisted state in the transaction. Use the transaction&#39;s own operations rather than queuing nested database calls. Bind results to the originating profile, world, lesson or attempt, and session; reject callbacks from a superseded session.</p><p>On response-save failure, retain the exact pending submission for retry without changing its first-response meaning. On lesson or Finish-save failure, retain the previous checkpoint and show Retry Save; do not display a new entry or unlock. An unsaved result may be explicitly discarded, and process loss before commit leaves it incomplete. A committed result survives interrupted scene return. Resolve or discard pending work before profile switching, then clear previous in-memory state before loading the next profile.</p><p>Reject unsupported versions, invalid IDs, impossible prerequisite stages, noncontiguous lesson progress, and inconsistent review/access state. Preserve corrupt or unknown data rather than overwriting it with defaults. Existing V2 progress does not automatically grant new lesson entries. The eventual schema change needs an explicit compatibility plan, synthetic-data migration checks, and tested in-place update recovery.</p><h2 id="verification-boundary">Verification boundary<a class="header-anchor" href="#verification-boundary" aria-label="Link to this section">​</a></h2><p>After FINAL approval, verify restart after each checkpoint, all 13 question mappings, wrong-answer correction, abandonment/replay, two-profile separation, duplicate/racing requests, failed writes, and interrupted scene return. Record named revision/build, device, expected result, and actual result. No database migration or runtime check was performed for this document. There are no required economy balances, purchase ledgers, teacher-service records, or synchronization tables.</p><p>The <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/design/database-schema.html">previous database reference</a> preserves the dated eight-table source snapshot, defects, and older schema proposals.</p></div>',1)])])}const m=t(r,[["render",o]]);export{u as __pageData,m as default};
